import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        String s = input.next();
        int maxLen = 0;
        int countWords = 0;
        String current = "";
        boolean insideParen = false;

        for (int idx = 0; idx < n; idx++) {
            char c = s.charAt(idx);
            if (c == '(') {
                maxLen = Math.max(maxLen, current.length());
                current = "";
                insideParen = true;
            } else if (c == ')') {
                if (current.length() > 0) {
                    countWords++;
                }
                current = "";
                insideParen = false;
            } else if (c == '_') {
                if (insideParen) {
                    if (current.length() > 0) {
                        countWords++;
                    }
                } else {
                    maxLen = Math.max(maxLen, current.length());
                }
                current = "";
            } else {
                current += c;
                if (idx == n - 1) {
                    maxLen = Math.max(maxLen, current.length());
                }
            }
        }
        System.out.println(maxLen + " " + countWords);
    }
}
